<?php
require __DIR__.'/auth.php';requireLogin();$user=currentUser();$today=date('Y-m-d');
$schedule=[['08:00','09:00','Breakfast','Idli / dosa / chapati + egg','🍳'],['10:30','11:00','Morning Snack','Banana or another fruit','🍌'],['12:00','13:00','Lunch','Rice + vegetables + fish/chicken/egg/dal','🍚'],['16:30','17:00','Evening Snack','Milk + guava + peanuts/almonds','🥛'],['20:00','21:00','During Duty','2 boiled eggs + banana','🥚'],['22:15','22:45','Dinner','Rice + fish/egg/chicken + vegetables','🍛']];$allowedMealNames=array_column($schedule,2);
$stmt=$db->prepare('SELECT id,lunch_date,food_item,quantity,notes,meal_type,meal_time,recorded_time,calories,protein,carbs,fat FROM lunches WHERE user_id=? AND lunch_date=? ORDER BY meal_time ASC,id DESC');$stmt->execute([$_SESSION['user_id'],$today]);$lunches=$stmt->fetchAll();
$stmt=$db->prepare('SELECT COUNT(*) FROM lunches WHERE user_id=?');$stmt->execute([$_SESSION['user_id']]);$totalAll=(int)$stmt->fetchColumn();$stmt=$db->prepare('SELECT COUNT(DISTINCT lunch_date) FROM lunches WHERE user_id=?');$stmt->execute([$_SESSION['user_id']]);$daysLogged=(int)$stmt->fetchColumn();$todayMeals=array_fill_keys($allowedMealNames,false);foreach($lunches as $row){if(isset($todayMeals[$row['meal_type']??'']))$todayMeals[$row['meal_type']]=true;}$completedMeals=count(array_filter($todayMeals));$mealProgress=(int)round($completedMeals/6*100);$todayCal=0;$todayProtein=0;foreach($lunches as $r){$todayCal+=(float)($r['calories']??0);$todayProtein+=(float)($r['protein']??0);}
function displayDate(string $iso):string{$t=strtotime($iso);return $t?date('d-m-Y',$t):$iso;}function displayTime(?string $iso):string{$t=$iso?strtotime($iso):false;return $t?date('h:i A',$t):'';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0f172a"><meta name="description" content="Personal meal and nutrition tracker"><link rel="manifest" href="manifest.json"><link rel="icon" href="assets/icon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/app.css"><title>Lunch Food Log</title><style>.hero-row{display:flex;align-items:center;gap:14px}.app-logo{width:70px;height:70px;border-radius:18px;box-shadow:0 8px 20px rgba(0,0,0,.25)}.progress{height:9px;background:#e5e7eb;border-radius:99px;overflow:hidden;margin-top:9px}.progress>span{display:block;height:100%;background:#2563eb;border-radius:99px}.meal.done{border-color:#bbf7d0;background:#f0fdf4}.done-mark{font-size:11px;color:#15803d;font-weight:900}.logout-btn{width:auto!important;margin:0!important}.quick-note{font-size:12px;color:var(--muted);margin:0}.search-wrap{margin-bottom:12px}.search-wrap input{background:#f8fafc}.empty{padding:25px 10px}.nutrition-mini{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}.nutrition-mini div{background:#f8fafc;border:1px solid var(--line);border-radius:12px;padding:9px}.nutrition-mini strong{display:block;font-size:15px}.nutrition-mini span{font-size:10px;color:var(--muted)}.ai-nutrition-card{margin:0 0 15px;padding:15px;border:1px solid #bfdbfe;border-radius:16px;background:linear-gradient(135deg,#eff6ff,#f8fafc)}.ai-title{font-size:16px;font-weight:900}.ai-help{font-size:12px;color:var(--muted);margin:5px 0 12px}.ai-buttons{display:grid;grid-template-columns:1fr 1fr;gap:9px}.ai-btn{display:flex;align-items:center;justify-content:center;border:0;border-radius:12px;padding:12px;background:#0f172a;color:#fff;font:800 12px system-ui;cursor:pointer;text-align:center}.ai-scan{background:#2563eb}.ai-status{font-size:11px;color:#166534;margin-top:9px;min-height:15px}.ai-status.bad{color:#b91c1c}@media(max-width:600px){.hero-row{align-items:flex-start}.app-logo{width:58px;height:58px;border-radius:15px}.hero h1{font-size:25px}.ai-buttons{grid-template-columns:1fr}}</style></head><body><main class="container"><header class="hero"><div class="hero-row"><img class="app-logo" src="assets/icon.svg" alt="Lunch Food Log app logo"><div><div class="eyebrow">Personal nutrition tracker</div><h1>Lunch Food Log</h1><p>Welcome, <?=h($user['name'])?>. Keep every meal organized.</p></div></div><div class="userbar"><span>👤 <?=h($user['email'])?></span><span><a href="profile.php">Profile</a> <a href="about.php">About</a> <form method="post" action="logout.php" style="display:inline"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><button class="logout-btn" type="submit">Logout</button></form></span></div></header><?php if(isset($_GET['saved'])):?><div class="flash">✓ Food entry saved successfully.</div><?php elseif(isset($_GET['updated'])):?><div class="flash">✓ Food entry updated successfully.</div><?php elseif(isset($_GET['deleted'])):?><div class="flash">✓ Food entry deleted.</div><?php endif;?><section class="stats"><div class="stat"><strong><?=$completedMeals?>/6</strong><span>Meals today</span></div><div class="stat"><strong><?=$daysLogged?></strong><span>Days logged</span></div><div class="stat"><strong><?=$totalAll?></strong><span>Total entries</span></div></section><section class="card"><div class="head"><div><h2>📈 Today's Progress</h2><p class="quick-note">Six meal windows · <?=h(date('d-m-Y'))?></p></div><span class="pill"><?=$mealProgress?>%</span></div><div class="progress"><span style="width:<?=$mealProgress?>%"></span></div><div class="nutrition-mini"><div><strong><?=number_format($todayCal,0)?> kcal</strong><span>Recorded calories</span></div><div><strong><?=number_format($todayProtein,1)?> g</strong><span>Recorded protein</span></div></div></section><section class="card"><div class="head"><h2>⏰ Daily Food Timetable</h2><small>6 meal windows</small></div><div class="schedule"><?php foreach($schedule as $m):$done=!empty($todayMeals[$m[2]]);?><div class="meal <?=$done?'done':''?>"><div class="icon"><?=$m[4]?></div><div><div class="meal-name"><?=h($m[2])?> <?php if($done):?><span class="done-mark">✓ Logged</span><?php endif;?></div><div class="time"><?=date('h:i A',strtotime($m[0]))?> – <?=date('h:i A',strtotime($m[1]))?></div><div class="foodhint"><?=h($m[3])?></div></div></div><?php endforeach;?></div><button id="mealNotifyButton" class="notify" type="button" onclick="enableMealReminders();">🔔 Enable Meal Notifications</button><div class="help">Browser/PWA reminders work when the app can run in the background.</div></section><section class="card"><div class="head"><h2>➕ Add Food Entry</h2><small>AI-assisted nutrition</small></div><form method="post" action="save.php" id="foodForm" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><div class="grid"><div><label>Date</label><input id="date_display" value="<?=h(displayDate($today))?>" placeholder="DD-MM-YYYY" inputmode="numeric" maxlength="10" required><input type="hidden" name="lunch_date" id="lunch_date" value="<?=h($today)"></div><div><label>Meal</label><select name="meal_type"><?php foreach($schedule as $m):?><option value="<?=h($m[2])?>" <?=$m[2]==='Lunch'?'selected':''?>><?=$m[4].' '.h($m[2])?></option><?php endforeach;?></select></div><div class="full"><label>Food Item</label><input name="food_item" maxlength="150" placeholder="e.g. Rice + Fish Curry" required></div><div><label>Quantity</label><input name="quantity" maxlength="80" placeholder="e.g. 1 plate"></div><div><label>Notes</label><input name="notes" maxlength="250" placeholder="Optional note"></div><div><label>Calories (kcal)</label><input type="number" name="calories" min="0" max="10000" step="0.1" placeholder="AI will estimate"></div><div><label>Protein (g)</label><input type="number" name="protein" min="0" max="1000" step="0.1" placeholder="AI will estimate"></div><div><label>Carbs (g)</label><input type="number" name="carbs" min="0" max="1000" step="0.1" placeholder="AI will estimate"></div><div><label>Fat (g)</label><input type="number" name="fat" min="0" max="1000" step="0.1" placeholder="AI will estimate"></div></div><button class="save">Save Food Entry</button></form></section><section class="card"><div class="head"><div><h2>🍽️ Today's Entries</h2><p class="quick-note">Search and manage your entries</p></div><span class="pill"><?=$totalAll?> total</span></div><?php if(!$lunches):?><div class="empty">No food entries recorded today.<br>Add your first meal above.</div><?php else:?><div class="search-wrap"><input type="search" id="foodSearch" placeholder="🔎 Search food, meal or notes..."></div><div class="entries" id="foodEntries"><?php foreach($lunches as $item):?><article class="entry"><div class="entrytop"><div class="food"><?=h($item['food_item'])?></div><div class="badge"><?=h($item['meal_type']??'Lunch')?></div></div><div class="meta">📅 <?=h(displayDate($item['lunch_date']))?> · ⏰ <?=h($item['meal_time']??'')?> · <?=h(displayTime($item['recorded_time']??''))?></div><?php if($item['quantity']):?><div class="meta"><strong>Quantity:</strong> <?=h($item['quantity'])?></div><?php endif;?><?php if((float)($item['calories']??0)>0||(float)($item['protein']??0)>0):?><div class="meta">🥗 <?=number_format((float)($item['calories']??0),0)?> kcal · 💪 <?=number_format((float)($item['protein']??0),1)?>g protein</div><?php endif;?><?php if($item['notes']):?><div class="notes">📝 <?=h($item['notes'])?></div><?php endif;?><div class="entry-actions"><a class="edit" href="edit.php?id=<?=urlencode($item['id'])?>">Edit</a><form method="post" action="delete.php" onsubmit="return confirm('Delete this food entry?');"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="id" value="<?=h($item['id'])?>"><button class="delete" type="submit">Delete</button></form></div></article><?php endforeach;?></div><div id="noSearchResults" class="empty" style="display:none">No matching entries.</div><?php endif;?></section><section class="card"><div class="head"><h2>⚡ Quick Access</h2></div><div class="actions"><a class="action primary" href="health.php">🧠 Health Dashboard</a><a class="action" href="reports.php">📊 Reports</a><a class="action" href="profile.php">👤 Profile</a><a class="action" href="about.php">ℹ️ About</a></div></section><div class="footer">Lunch Food Log · Developed by AFSAL PG · <?=date('Y')?></div></main><script src="assets/meal-alert.js" defer></script><script src="assets/ai-nutrition.js" defer></script><script>function isoFromDisplay(v){const m=v.trim().match(/^(\d{2})-(\d{2})-(\d{4})$/);if(!m)return null;const d=+m[1],mo=+m[2],y=+m[3],x=new Date(Date.UTC(y,mo-1,d));return x.getUTCFullYear()===y&&x.getUTCMonth()===mo-1&&x.getUTCDate()===d?`${y}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`:null}document.getElementById('foodForm').addEventListener('submit',e=>{const iso=isoFromDisplay(document.getElementById('date_display').value);if(!iso){e.preventDefault();alert('Please enter a valid date in DD-MM-YYYY format.');return}document.getElementById('lunch_date').value=iso});const s=document.getElementById('foodSearch'),cards=document.querySelectorAll('#foodEntries .entry'),none=document.getElementById('noSearchResults');if(s)s.addEventListener('input',()=>{const q=s.value.toLowerCase();let n=0;cards.forEach(c=>{const ok=c.textContent.toLowerCase().includes(q);c.style.display=ok?'':'none';if(ok)n++});if(none)none.style.display=n?'none':''});</script></body></html>
